#!/usr/bin/env node
// Generates the Host API v1 command constants from schema/host-api/v1/commands.json.
//
//   node scripts/generate-host-api.mjs           write the generated files
//   node scripts/generate-host-api.mjs --check   fail when a generated file is stale
//
// Two consumers: the Node route layer and desktop host
// (extension/routes/host-api/commands.generated.mjs, which also carries every command's
// request/result schema for frame validation) and the SharedProtocol Swift package
// (ios_app/SharedProtocol/Sources/SharedProtocol: the command constants in HostApiCommands.swift
// and the parsed schema tables in HostApiSchemas.swift, for HostApiSchemaValidator).
// Third consumer: the web client (web/src/host-api/types.generated.ts), TypeScript types only.
// Output is deterministic (commands sorted by name), so --check is a byte comparison.
import { readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs";
import { join, resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const registry = JSON.parse(readFileSync(join(ROOT, "schema/host-api/v1/commands.json"), "utf8"));
const names = Object.keys(registry.commands).sort();
const check = process.argv.includes("--check");
const header = "// GENERATED by scripts/generate-host-api.mjs from schema/host-api/v1/commands.json. Do not edit.";

// host.auth.pair -> hostAuthPair; toolApprovals.answer -> toolApprovalsAnswer.
const swiftCase = (name) =>
  name
    .split(".")
    .map((part, i) => (i === 0 ? part : part[0].toUpperCase() + part.slice(1)))
    .join("");

// Read before the js template: the envelope and event schemas are embedded in the Node output.
const readSchema = (f) => JSON.parse(readFileSync(join(ROOT, "schema/host-api/v1", f), "utf8"));
const envelopeSchema = readSchema("envelope.schema.json");
const eventsSchema = readSchema("events.schema.json");
// Event names, for the Swift client's HostApiEvent (sorted, so --check stays a byte comparison).
const eventNames = eventsSchema.oneOf.map((v) => v.properties.command.const).sort();

const js = `${header}
export const HOST_API_VERSION = ${registry.version};
export const HOST_API_LIMITS = Object.freeze(${JSON.stringify(registry.limits)});
export const HOST_API_COMMANDS = Object.freeze({
${names.map((n) => `  ${JSON.stringify(n)}: Object.freeze({ capability: ${JSON.stringify(registry.commands[n].capability)}, idempotent: ${registry.commands[n].idempotent} })`).join(",\n")}
});
export const HOST_API_SCHEMAS = Object.freeze({
${names.map((n) => `  ${JSON.stringify(n)}: Object.freeze({ request: ${JSON.stringify(registry.commands[n].request)}, result: ${JSON.stringify(registry.commands[n].result)} })`).join(",\n")}
});

export const HOST_API_ENVELOPE = Object.freeze(${JSON.stringify(envelopeSchema)});
export const HOST_API_EVENTS = Object.freeze(${JSON.stringify(eventsSchema)});
`;

const swift = `${header}
public struct HostApiLimits: Sendable {
    public let maxFrameBytes: Int
    public let defaultListItems: Int
    public let maxListItems: Int
    public let maxListBytes: Int

    public init(maxFrameBytes: Int, defaultListItems: Int, maxListItems: Int, maxListBytes: Int) {
        self.maxFrameBytes = maxFrameBytes
        self.defaultListItems = defaultListItems
        self.maxListItems = maxListItems
        self.maxListBytes = maxListBytes
    }
}

public enum HostApiCommand: String, CaseIterable, Sendable {
${names.map((n) => `    case ${swiftCase(n)} = ${JSON.stringify(n)}`).join("\n")}

    public var capability: String {
        switch self {
${names.map((n) => `        case .${swiftCase(n)}: return ${JSON.stringify(registry.commands[n].capability)}`).join("\n")}
        }
    }

    public var idempotent: Bool {
        switch self {
${names.map((n) => `        case .${swiftCase(n)}: return ${registry.commands[n].idempotent}`).join("\n")}
        }
    }
}

public enum HostApi {
    public static let version = ${registry.version}
    public static let limits = HostApiLimits(maxFrameBytes: ${registry.limits.maxFrameBytes}, defaultListItems: ${registry.limits.defaultListItems}, maxListItems: ${registry.limits.maxListItems}, maxListBytes: ${registry.limits.maxListBytes})
    public static let commands: [String: HostApiCommand] = [
${names.map((n) => `        ${JSON.stringify(n)}: .${swiftCase(n)}`).join(",\n")}
    ]
}

public enum HostApiEvent: String, CaseIterable, Sendable {
${eventNames.map((n) => `    case ${swiftCase(n)} = ${JSON.stringify(n)}`).join("\n")}
}
`;

// The schema tables let Swift judge frames exactly like the Node gate (HostApiSchemaValidator).
const schemaTable = {
  envelope: readSchema("envelope.schema.json"),
  events: readSchema("events.schema.json"),
  commands: Object.fromEntries(names.map((n) => [n, { request: registry.commands[n].request, result: registry.commands[n].result }])),
};
const schemaText = JSON.stringify(schemaTable);
if (schemaText.includes('"##')) throw new Error('host-api: schema text contains "##, pick a longer Swift raw-string delimiter');

const swiftSchemas = `${header}
import Foundation

/// The Host API v1 schemas as parsed JSON, for \`HostApiSchemaValidator\`.
public enum HostApiSchemas {
    private static let table: [String: Any] = {
        let text = ##"${schemaText}"##
        return (try? JSONSerialization.jsonObject(with: Data(text.utf8))) as? [String: Any] ?? [:]
    }()

    public static var envelope: [String: Any] { table["envelope"] as? [String: Any] ?? [:] }
    public static var events: [String: Any] { table["events"] as? [String: Any] ?? [:] }

    public static func request(for command: HostApiCommand) -> [String: Any] {
        ((table["commands"] as? [String: Any])?[command.rawValue] as? [String: Any])?["request"] as? [String: Any] ?? [:]
    }

    public static func result(for command: HostApiCommand) -> [String: Any] {
        ((table["commands"] as? [String: Any])?[command.rawValue] as? [String: Any])?["result"] as? [String: Any] ?? [:]
    }
}
`;

// One Codable struct per payload schema. The mapping is deliberately narrow: a schema shape it does not
// know fails generation loudly instead of producing a lossy type.
const pascal = (name) => name.split(".").map((p) => p[0].toUpperCase() + p.slice(1)).join("");
const structs = [];

function swiftType(schema, name) {
  switch (schema.type) {
    case "string": return "String";
    case "integer": return "Int";
    case "number": return "Double";
    case "boolean": return "Bool";
    case "array": return `[${swiftType(schema.items, `${name}Item`)}]`;
    case "object": {
      if (!schema.properties && schema.additionalProperties && typeof schema.additionalProperties === "object") {
        const v = schema.additionalProperties;
        if (v.type === "object" && !v.properties) return "[String: HostApiJSONValue]";
        return `[String: ${swiftType(v, `${name}Value`)}]`;
      }
      emitStruct(name, schema);
      return name;
    }
    default:
      throw new Error(`host-api: no Swift type for ${name}: ${JSON.stringify(schema)}`);
  }
}

function emitStruct(name, schema) {
  const required = new Set(schema.required || []);
  const fields = Object.keys(schema.properties || {}).sort().map((prop) => {
    if (!/^[a-z][A-Za-z0-9]*$/.test(prop)) throw new Error(`host-api: ${name}.${prop} is not a Swift identifier`);
    const t = swiftType(schema.properties[prop], `${name}${prop[0].toUpperCase()}${prop.slice(1)}`);
    return { prop, type: required.has(prop) ? t : `${t}?`, optional: !required.has(prop) };
  });
  const lines = [`public struct ${name}: Codable, Equatable, Sendable {`];
  for (const f of fields) lines.push(`    public var ${f.prop}: ${f.type}`);
  const params = fields.map((f) => `${f.prop}: ${f.type}${f.optional ? " = nil" : ""}`).join(", ");
  lines.push("", `    public init(${params}) {`);
  for (const f of fields) lines.push(`        self.${f.prop} = ${f.prop}`);
  lines.push("    }", "}");
  structs.push(lines.join("\n"));
}

for (const n of names) {
  swiftType(registry.commands[n].request, `HostApi${pascal(n)}Request`);
  swiftType(registry.commands[n].result, `HostApi${pascal(n)}Result`);
}
for (const variant of schemaTable.events.oneOf) {
  const event = variant.properties.command.const;
  swiftType(variant.properties.payload, `HostApi${pascal(event)}Event`);
}

const swiftPayloads = `${header}
import Foundation

${structs.join("\n\n")}
`;

// TypeScript for the web client (web/): the same schemas as types only. The host validates every frame it sends;
// the client checks just the fields it reads. A shape this mapping does not know fails generation loudly.
const TS_REFS = { "#/$defs/ErrorCode": "HostApiErrorCode" };
function tsType(schema) {
  if (schema.$ref) {
    if (!TS_REFS[schema.$ref]) throw new Error(`host-api: no TypeScript type for $ref ${schema.$ref}`);
    return TS_REFS[schema.$ref];
  }
  if (schema.const !== undefined) return JSON.stringify(schema.const);
  if (schema.enum) return schema.enum.map((v) => JSON.stringify(v)).join(" | ");
  switch (schema.type) {
    case "string": return "string";
    case "integer": return "number";
    case "number": return "number";
    case "boolean": return "boolean";
    case "array": return `Array<${tsType(schema.items)}>`;
    case "object": {
      const keys = Object.keys(schema.properties || {}).sort();
      if (!keys.length) {
        const ap = schema.additionalProperties;
        if (ap === false) return "Record<string, never>";
        if (ap && typeof ap === "object") return `Record<string, ${ap.type === "object" && !ap.properties ? "Record<string, unknown>" : tsType(ap)}>`;
        return "Record<string, unknown>";
      }
      const required = new Set(schema.required || []);
      return `{ ${keys.map((k) => {
        if (!/^[A-Za-z_$][\w$]*$/.test(k)) throw new Error(`host-api: ${k} is not a TypeScript identifier`);
        return `${k}${required.has(k) ? "" : "?"}: ${tsType(schema.properties[k])}`;
      }).join("; ")} }`;
    }
    default:
      throw new Error(`host-api: no TypeScript type for ${JSON.stringify(schema)}`);
  }
}

const tsEvents = schemaTable.events.oneOf
  .map((v) => [v.properties.command.const, v.properties.payload])
  .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));

const ts = `${header}
// Types for the web client. Types only: the host validates every frame it sends.
export const HOST_API_VERSION = ${registry.version};
export const HOST_API_LIMITS = ${JSON.stringify(registry.limits)} as const;
export const HOST_API_CAPABILITIES = ${JSON.stringify(registry.capabilities)} as const;
export type HostApiCapability = (typeof HOST_API_CAPABILITIES)[number];
export const HOST_API_ERROR_CODES = ${JSON.stringify(schemaTable.envelope.$defs.ErrorCode.enum)} as const;
export type HostApiErrorCode = (typeof HOST_API_ERROR_CODES)[number];
export type HostApiErrorBody = ${tsType(schemaTable.envelope.$defs.Error)};
export const HOST_API_COMMANDS = {
${names.map((n) => `  ${JSON.stringify(n)}: { capability: ${JSON.stringify(registry.commands[n].capability)}, idempotent: ${registry.commands[n].idempotent} },`).join("\n")}
} as const;
export type HostApiCommandName = keyof typeof HOST_API_COMMANDS;
export interface HostApiCommandMap {
${names.map((n) => `  ${JSON.stringify(n)}: { request: ${tsType(registry.commands[n].request)}; result: ${tsType(registry.commands[n].result)} };`).join("\n")}
}
export type HostApiRequest<C extends HostApiCommandName> = HostApiCommandMap[C]["request"];
export type HostApiResult<C extends HostApiCommandName> = HostApiCommandMap[C]["result"];
export const HOST_API_EVENT_NAMES = ${JSON.stringify(tsEvents.map(([e]) => e))} as const;
export type HostApiEventName = (typeof HOST_API_EVENT_NAMES)[number];
export interface HostApiEventMap {
${tsEvents.map(([e, p]) => `  ${JSON.stringify(e)}: ${tsType(p)};`).join("\n")}
}
`;

const outputs = [
  ["extension/routes/host-api/commands.generated.mjs", js],
  ["ios_app/SharedProtocol/Sources/SharedProtocol/HostApiCommands.swift", swift],
  ["ios_app/SharedProtocol/Sources/SharedProtocol/HostApiSchemas.swift", swiftSchemas],
  ["ios_app/SharedProtocol/Sources/SharedProtocol/HostApiPayloads.swift", swiftPayloads],
  ["web/src/host-api/types.generated.ts", ts],
];

let stale = false;
for (const [rel, content] of outputs) {
  const path = join(ROOT, rel);
  if (check) {
    if (!existsSync(path) || readFileSync(path, "utf8") !== content) {
      console.error(`host-api: ${rel} is stale (run node scripts/generate-host-api.mjs)`);
      stale = true;
    }
  } else {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, content);
  }
}
if (stale) process.exit(1);
if (!check) console.log(`host-api: wrote ${outputs.length} generated files`);
